  //! UPDATE THIS WITH CATEGORY IDs FOR WHICH TO SHOW ARTICLE THUMBNAILS
  const CATEGORIES_WITH_VIDEO_ARTICLES = [
    // '7185486681373', // Capture One Learn
  ]

  //! DO NOT EDIT ANY FURTHER!
  function AddThumbnailsToArticles(listOfArticles) {
    const IS_PAGE_WITH_VIDEO_ARTICLES = listOfArticles.some((page) => window.location.pathname.includes(page));
    const ARTICLES_LIST_HOLDER = document.getElementsByClassName('article-list');

    if (IS_PAGE_WITH_VIDEO_ARTICLES) {
      const styleSheet = document.getElementById("article-thumbnail-style");
      styleSheet.href = "/hc/theming_assets/01HZPEXFG13BSBAGMX3RX417JX";

      Array.from(ARTICLES_LIST_HOLDER).forEach((articleHolder) => {
        Array.from(articleHolder.getElementsByClassName('article-list-link')).forEach((articleLink) => {
          var thumbnailImage = document.createElement('img');
          thumbnailImage.className = 'article-thumbnail';
          thumbnailImage.src = "/hc/theming_assets/01HZPEXFG175RRJZQFVVWQB67V";

          // Clone the title with link element to put the thumbnail inside
          // We will use it so that the thumbnail also links to the article (so you can click it!)
          var thumbnailElement = articleLink.cloneNode(false);
          thumbnailElement.className = 'article-list-thumbnail';
          thumbnailElement.innerHTML = thumbnailImage.outerHTML;

          // Add the new thumbnail element at the top of the list so it comes above the title
          articleLink.parentNode.parentNode.prepend(thumbnailElement);
        });
      });
    }
  }

  AddThumbnailsToArticles(CATEGORIES_WITH_VIDEO_ARTICLES);
</script>
